class BSTIterator {
  std::stack<TreeNode*> st_;           // the left spine still to visit: O(h) memory
  void pushLeft(TreeNode* n) {
    for (; n; n = n->left) st_.push(n);
  }
public:
  explicit BSTIterator(TreeNode* root) { pushLeft(root); }

  int next() {                         // amortized O(1): every node is pushed and popped once
    TreeNode* n = st_.top();
    st_.pop();
    pushLeft(n->right);
    return n->val;
  }
  bool hasNext() const { return !st_.empty(); }
};

