Node* connect(Node* root) {
    Node* head = root;                  // first node of the current level
    while (head) {
        Node dummy(0);                  // sentinel in front of the next level
        Node* tail = &dummy;
        for (Node* p = head; p; p = p->next) {   // current level is already linked
            if (p->left)  { tail->next = p->left;  tail = tail->next; }
            if (p->right) { tail->next = p->right; tail = tail->next; }
        }
        head = dummy.next;              // nullptr when there is no next level
    }
    return root;
}

