vector<vector<int>> verticalTraversal(TreeNode* root) {
    vector<tuple<int, int, int>> pts;                 // (col, row, val)
    vector<tuple<TreeNode*, int, int>> st;            // iterative DFS: (node, row, col)
    if (root) st.emplace_back(root, 0, 0);
    while (!st.empty()) {
        auto [n, r, c] = st.back(); st.pop_back();
        pts.emplace_back(c, r, n->val);
        if (n->left)  st.emplace_back(n->left,  r + 1, c - 1);
        if (n->right) st.emplace_back(n->right, r + 1, c + 1);
    }
    sort(pts.begin(), pts.end());                     // exactly the required order
    vector<vector<int>> out;
    for (size_t i = 0; i < pts.size(); ++i) {
        if (i == 0 || get<0>(pts[i]) != get<0>(pts[i - 1])) out.emplace_back();
        out.back().push_back(get<2>(pts[i]));
    }
    return out;
}

