void recoverTree(TreeNode* root) {
    TreeNode *first = nullptr, *second = nullptr, *prev = nullptr;
    stack<TreeNode*> st;
    TreeNode* cur = root;
    while (cur || !st.empty()) {          // iterative inorder
        while (cur) { st.push(cur); cur = cur->left; }
        cur = st.top(); st.pop();
        if (prev && prev->val > cur->val) {   // a descent in the inorder
            if (!first) first = prev;         // larger value of the first descent
            second = cur;                     // smaller value of the last descent
        }
        prev = cur;
        cur = cur->right;
    }
    if (first) swap(first->val, second->val);
}

