TreeNode* treeToDoublyList(TreeNode* root) {
    if (!root) return nullptr;
    TreeNode *head = nullptr, *prev = nullptr;
    stack<TreeNode*> st;
    TreeNode* cur = root;
    while (cur || !st.empty()) {              // iterative inorder
        while (cur) { st.push(cur); cur = cur->left; }
        cur = st.top(); st.pop();
        if (prev) { prev->right = cur; cur->left = prev; }   // link in sorted order
        else head = cur;
        prev = cur;
        cur = cur->right;   // still the original child: only prev's fields were changed
    }
    head->left = prev;      // close the circle
    prev->right = head;
    return head;
}

