// Format: level order, ',' between tokens, '#' for null.
// Every non-null node contributes exactly two child tokens, so decoding is unambiguous.
class Codec {
public:
    string serialize(TreeNode* root) {
        string out;
        queue<TreeNode*> q;
        q.push(root);
        while (!q.empty()) {
            TreeNode* n = q.front(); q.pop();
            if (!out.empty()) out += ',';
            if (!n) { out += '#'; continue; }
            out += to_string(n->val);
            q.push(n->left);
            q.push(n->right);
        }
        return out;
    }

    TreeNode* deserialize(const string& data) {
        vector<string> tok;
        stringstream ss(data);
        for (string t; getline(ss, t, ','); ) tok.push_back(t);
        auto make = [&](size_t i) -> TreeNode* {
            return (i >= tok.size() || tok[i] == "#") ? nullptr : new TreeNode(stoi(tok[i]));
        };
        TreeNode* root = make(0);
        queue<TreeNode*> q;
        if (root) q.push(root);
        size_t i = 1;
        while (!q.empty()) {          // each node consumes the next two tokens
            TreeNode* n = q.front(); q.pop();
            n->left = make(i++);
            n->right = make(i++);
            if (n->left) q.push(n->left);
            if (n->right) q.push(n->right);
        }
        return root;
    }
};

