class Codec:
    # Format: preorder of "value childCount" pairs, space separated.
    def serialize(self, root):
        if root is None:
            return ""
        out, stack = [], [root]
        while stack:
            n = stack.pop()
            out.append(f"{n.val} {len(n.children)}")
            stack.extend(reversed(n.children))   # leftmost child is processed first
        return " ".join(out)

    def deserialize(self, data):
        if not data:
            return None
        it = iter(map(int, data.split()))
        root = Node(next(it))
        stack = [[root, next(it)]]               # [node, children still to read]
        while stack:
            top = stack[-1]
            if top[1] == 0:
                stack.pop()
                continue
            top[1] -= 1
            child = Node(next(it))
            top[0].children.append(child)
            stack.append([child, next(it)])
        return root

