    TreeNode *left, *right;
    TreeNode(int v, TreeNode* l = nullptr, TreeNode* r = nullptr) : val(v), left(l), right(r) {}
};

TreeNode* buildTree(const vector<int>& inorder, const vector<int>& postorder) {
    unordered_map<int, int> pos;                 // value -> index in inorder
    for (int i = 0; i < (int)inorder.size(); ++i) pos[inorder[i]] = i;
    int next = (int)postorder.size() - 1;        // postorder read backwards: root, right, left
    function<TreeNode*(int, int)> go = [&](int lo, int hi) -> TreeNode* {
        if (lo > hi) return nullptr;
        TreeNode* n = new TreeNode(postorder[next--]);
        int m = pos[n->val];
        n->right = go(m + 1, hi);                // right subtree must be built first
        n->left = go(lo, m - 1);
        return n;
    };
    return go(0, (int)inorder.size() - 1);
}

// p ו-q מובטחים להיות בעץ ושונים זה מזה
TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {
    if (!root || root == p || root == q) return root;   // מצאנו אחד מהם (או ריק)
    TreeNode* l = lowestCommonAncestor(root->left, p, q);
    TreeNode* r = lowestCommonAncestor(root->right, p, q);
    if (l && r) return root;      // אחד מכל צד: root הוא הפיצול
    return l ? l : r;             // שניהם באותו צד (או אף אחד)
}

int dfs(TreeNode* node, long long sum, int target, unordered_map<long long, int>& seen) {
    if (!node) return 0;
    sum += node->val;                                  // prefix sum מהשורש עד node
    int count = seen.count(sum - target) ? seen[sum - target] : 0;
    ++seen[sum];                                       // node נכנס למסלול
    count += dfs(node->left, sum, target, seen);
    count += dfs(node->right, sum, target, seen);
    --seen[sum];                                       // node יוצא: backtrack
    return count;
}
int pathSum(TreeNode* root, int target) {
    unordered_map<long long, int> seen{{0, 1}};        // מסלול שמתחיל בשורש
    return dfs(root, 0, target, seen);
}

