// left = prev, right = next. רמה 0 משמאל לימין, רמה 1 מימין לשמאל, וכן הלאה.
TreeNode* spiralToDLL(TreeNode* root) {
    if (!root) return nullptr;
    vector<TreeNode*> order, level{root};
    bool leftToRight = true;
    while (!level.empty()) {
        if (leftToRight) order.insert(order.end(), level.begin(), level.end());
        else order.insert(order.end(), level.rbegin(), level.rend());
        vector<TreeNode*> next;
        for (TreeNode* n : level) {                    // קוראים ילדים לפני שמשנים מצביעים
            if (n->left) next.push_back(n->left);
            if (n->right) next.push_back(n->right);
        }
        level = move(next);
        leftToRight = !leftToRight;
    }
    for (size_t i = 0; i < order.size(); ++i) {        // רק עכשיו דורסים left/right
        order[i]->left = i ? order[i - 1] : nullptr;
        order[i]->right = i + 1 < order.size() ? order[i + 1] : nullptr;
    }
    return order[0];
}

def longest_consecutive(root):
    """root.children: list. אורך (בצמתים) של מסלול יורד הארוך ביותר שבו כל ילד = הורה + 1."""
    if root is None:
        return 0
    best = 1
    stack = [(root, 1)]                    # (צומת, אורך הרצף שמסתיים בו)
    while stack:
        node, length = stack.pop()
        best = max(best, length)
        for child in node.children:
            stack.append((child, length + 1 if child.val == node.val + 1 else 1))
    return best

def distinct_downward_sums(root):
    """מספר הסכומים השונים של כל המסלולים היורדים (מתחילים בכל צומת, יורדים לצאצא, לפחות צומת אחד)."""
    seen = set()
    stack = [(root, [])] if root else []   # [] = סכומי כל המסלולים שמסתיימים בהורה
    while stack:
        node, parent_sums = stack.pop()
        ending_here = [s + node.val for s in parent_sums] + [node.val]
        seen.update(ending_here)
        for child in (node.left, node.right):
            if child:
                stack.append((child, ending_here))
    return len(seen)

vector<int> distanceK(TreeNode* root, TreeNode* target, int k) {
    unordered_map<TreeNode*, TreeNode*> parent;        // הופכים את העץ לגרף לא מכוון
    vector<TreeNode*> st{root};
    parent[root] = nullptr;
    while (!st.empty()) {
        TreeNode* n = st.back(); st.pop_back();
        for (TreeNode* c : {n->left, n->right})
            if (c) { parent[c] = n; st.push_back(c); }
    }
    unordered_set<TreeNode*> seen{target};
    vector<TreeNode*> level{target};
    for (int d = 0; d < k && !level.empty(); ++d) {    // BFS בשכבות, k צעדים
        vector<TreeNode*> next;
        for (TreeNode* n : level)
            for (TreeNode* nb : {n->left, n->right, parent[n]})
                if (nb && seen.insert(nb).second) next.push_back(nb);
        level = move(next);
    }
    vector<int> out;
    for (TreeNode* n : level) out.push_back(n->val);
    return out;
}

