int bstDistance(TreeNode* root, int a, int b) {
    if (a > b) swap(a, b);
    TreeNode* cur = root;
    while (true) {                                     // יורדים עד נקודת הפיצול (LCA)
        if (b < cur->val) cur = cur->left;
        else if (a > cur->val) cur = cur->right;
        else break;                                    // a <= cur->val <= b
    }
    return depthFrom(cur, a) + depthFrom(cur, b);
}

// כל צומת מקבל את סכום הערכים המקוריים של שני תתי-העצים שלו; עלה מקבל 0.
// מחזירה את הסכום המקורי של כל תת-העץ (כולל node).
long long toSumTree(TreeNode* node) {
    if (!node) return 0;
    long long old = node->val;
    long long below = toSumTree(node->left) + toSumTree(node->right);
    node->val = (int)below;
    return below + old;
