// מחזירה את ה"זרוע" הטובה ביותר שיורדת מ-node (ענף אחד), ומעדכנת best במסלול עם כיפוף ב-node
int arm(TreeNode* node, int& best) {
    if (!node) return 0;
    int l = max(0, arm(node->left, best));             // ענף שלילי? לא לוקחים אותו
    int r = max(0, arm(node->right, best));
    best = max(best, node->val + l + r);               // מסלול שמתכופף ב-node
    return node->val + max(l, r);                      // להורה מותר להמשיך רק בצד אחד
}
