TreeNode* deleteNode(TreeNode* root, int key) {
    if (!root) return nullptr;                         // המפתח לא נמצא
    if (key < root->val) { root->left = deleteNode(root->left, key); return root; }
    if (key > root->val) { root->right = deleteNode(root->right, key); return root; }
    if (!root->left || !root->right) {                 // 0 או 1 ילדים: הילד עולה למקום
        TreeNode* child = root->left ? root->left : root->right;
        delete root;
        return child;
    }
    TreeNode* succ = root->right;                      // inorder successor: השמאלי ביותר מימין
    while (succ->left) succ = succ->left;
    root->val = succ->val;                             // מעתיקים ומוחקים את ה-successor
    root->right = deleteNode(root->right, succ->val);
    return root;
}

