def diameter(root):
    """מספר הקשתות במסלול הארוך ביותר בין שני צמתים. איטרטיבי (postorder) כדי לא להיתקע ב-recursion limit."""
    height = {None: 0}                     # גובה בצמתים; לעץ ריק 0
    best = 0
    stack = [(root, False)] if root else []
    while stack:
        node, done = stack.pop()
        if done:
            l, r = height[node.left], height[node.right]
            best = max(best, l + r)        # קשתות במסלול שמתכופף ב-node
            height[node] = 1 + max(l, r)
        else:
            stack.append((node, True))
            for child in (node.left, node.right):
                if child:
                    stack.append((child, False))
    return best

bool areMirrors(const TreeNode* a, const TreeNode* b) {
    vector<pair<const TreeNode*, const TreeNode*>> st{{a, b}};   // איטרטיבי: אין stack overflow
    while (!st.empty()) {
        auto [x, y] = st.back(); st.pop_back();
        if (!x && !y) continue;
        if (!x || !y || x->val != y->val) return false;
        st.push_back({x->left, y->right});             // שמאל מול ימין
        st.push_back({x->right, y->left});             // ימין מול שמאל
    }
    return true;
}

// struct Node { int val; Node *left, *right, *parent; };
Node* lowestCommonAncestor(Node* p, Node* q) {
    Node* a = p;
    Node* b = q;
    while (a != b) {                                   // כל אחד עובר depth(p) + depth(q) + 2 צעדים לכל היותר
        a = a ? a->parent : q;                         // סוף השרשרת? ממשיכים מההתחלה של השני
        b = b ? b->parent : p;
    }
    return a;                                          // נפגשים ב-LCA (קיים, כי שניהם באותו עץ)
}
